const $=(s,r=document)=>r.querySelector(s);
const nav=$('#mobile-nav'),toggle=$('.mobile-toggle');
function closeMenu(){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir menú')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.querySelectorAll('.reel-menu').forEach(m=>{m.hidden=true;m.previousElementSibling?.setAttribute('aria-expanded','false')})}});
let lastFocus;const reelStates=new Map();
function playVisible(){if(document.hidden||document.querySelector('dialog[open]'))return;for(const [video,state] of reelStates){if(state.visible&&!state.userPaused)video.play().catch(()=>{})}}
function openDialog(dialog){closeMenu();lastFocus=document.activeElement;for(const video of reelStates.keys())video.pause();dialog.showModal();document.body.style.overflow='hidden'}
document.querySelectorAll('dialog').forEach(dialog=>{ $('[data-close]',dialog).addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus();playVisible()});dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close()})});
document.querySelectorAll('[data-reserve]').forEach(b=>b.addEventListener('click',()=>openDialog($('#reservation-dialog'))));$('[data-credits]').addEventListener('click',()=>openDialog($('#credits-dialog')));
const icons={play:'<path d="m6 3 12 9-12 9Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',muted:'<path d="M11 5 6 9H3v6h3l5 4Z"/><path d="m16 9 6 6m0-6-6 6"/>',sound:'<path d="M11 5 6 9H3v6h3l5 4Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',full:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>'};
function iconButton(name,label){const b=document.createElement('button');b.type='button';b.setAttribute('aria-label',label);b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[name]+'</svg>';return b}
function setIcon(button,name,label){button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[name]+'</svg>';button.setAttribute('aria-label',label);button.title=label}
const observer=new IntersectionObserver(entries=>{for(const entry of entries){const video=entry.target,state=reelStates.get(video);state.visible=entry.isIntersecting&&entry.intersectionRatio>=.25;if(state.visible){if(!video.getAttribute('src')){video.src=video.dataset.src;video.load()}if(!state.userPaused&&!document.hidden&&!document.querySelector('dialog[open]'))video.play().catch(()=>{})}else{video.pause()}}},{threshold:[0,.25,.6]});
document.addEventListener('visibilitychange',()=>{if(document.hidden){for(const video of reelStates.keys())video.pause()}else playVisible()});
const track=$('#reels-track');let total=0;
function updatePosition(){if(!track.children.length)return;const left=track.getBoundingClientRect().left+parseFloat(getComputedStyle(track).paddingLeft);let nearest=0,distance=Infinity;[...track.children].forEach((card,i)=>{const d=Math.abs(card.getBoundingClientRect().left-left);if(d<distance){distance=d;nearest=i}});$('#reels-status').textContent=String(nearest+1).padStart(2,'0')+' / '+String(total).padStart(2,'0');$('#reels-prev').disabled=track.scrollLeft<2;$('#reels-next').disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-3}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function shift(direction){const card=track.querySelector('.reel-card');if(card)track.scrollBy({left:direction*(card.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap)),behavior:reduced.matches?'instant':'smooth'})}
$('#reels-prev').addEventListener('click',()=>shift(-1));$('#reels-next').addEventListener('click',()=>shift(1));track.addEventListener('scroll',updatePosition,{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();shift(e.key==='ArrowRight'?1:-1)}});
function reelCard(reel,index){const card=document.createElement('article');card.className='reel-card';card.setAttribute('aria-label','Reel '+(index+1)+' de La Corte Italiana');const video=document.createElement('video');video.muted=true;video.defaultMuted=true;video.autoplay=true;video.loop=true;video.playsInline=true;video.preload='none';video.poster=reel.poster;video.dataset.src=reel.video||'';video.setAttribute('aria-label','Vídeo '+(index+1)+' de La Corte Italiana');video.setAttribute('playsinline','');const state={visible:false,userPaused:false};reelStates.set(video,state);
const top=document.createElement('div');top.className='reel-top';const avatar=document.createElement('img');avatar.className='reel-avatar';avatar.src='assets/logo.jpg';avatar.alt='';const name=document.createElement('span');name.textContent='lacorteitaliana';const options=document.createElement('button');options.className='reel-options';options.append(corteIcon('more'));options.setAttribute('aria-label','Opciones del reel '+(index+1));options.setAttribute('aria-expanded','false');const menu=document.createElement('div');menu.className='reel-menu';menu.id='reel-menu-'+index;menu.hidden=true;options.setAttribute('aria-controls',menu.id);const source=document.createElement('a');source.href=reel.url;source.target='_blank';source.rel='noopener';source.textContent='Ver original en Instagram ';source.append(corteIcon('ne'));const restart=document.createElement('button');restart.textContent='Reproducir desde el inicio';restart.addEventListener('click',()=>{video.currentTime=0;state.userPaused=false;video.play().catch(()=>{});menu.hidden=true;options.setAttribute('aria-expanded','false')});menu.append(source,restart);options.addEventListener('click',()=>{const open=menu.hidden;document.querySelectorAll('.reel-menu').forEach(m=>{m.hidden=true;m.previousElementSibling?.setAttribute('aria-expanded','false')});menu.hidden=!open;options.setAttribute('aria-expanded',String(open))});top.append(avatar,name,options,menu);
const bottom=document.createElement('div');bottom.className='reel-bottom';const caption=document.createElement('span');caption.className='reel-caption';caption.textContent=String(index+1).padStart(2,'0')+' — La Corte, en vivo.';const controls=document.createElement('div');controls.className='reel-controls';const play=iconButton('play','Reproducir reel '+(index+1));const sound=iconButton('muted','Activar sonido del reel '+(index+1));sound.setAttribute('aria-pressed','false');const full=iconButton('full','Ver reel '+(index+1)+' a pantalla completa');full.className='reel-fullscreen';play.addEventListener('click',()=>{if(video.paused){if(!video.getAttribute('src'))video.src=video.dataset.src;state.userPaused=false;video.play().catch(()=>{})}else{state.userPaused=true;video.pause()}});video.addEventListener('play',()=>setIcon(play,'pause','Pausar reel '+(index+1)));video.addEventListener('pause',()=>setIcon(play,'play','Reproducir reel '+(index+1)));sound.addEventListener('click',()=>{const unmute=video.muted;for(const other of reelStates.keys()){if(other!==video)other.muted=true}video.muted=!unmute});video.addEventListener('volumechange',()=>{setIcon(sound,video.muted?'muted':'sound',(video.muted?'Activar':'Desactivar')+' sonido del reel '+(index+1));sound.setAttribute('aria-pressed',String(!video.muted))});full.addEventListener('click',()=>{if(card.requestFullscreen)card.requestFullscreen().catch(()=>{});else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen()});controls.append(play,sound,full);const progress=document.createElement('div');progress.className='reel-progress';progress.setAttribute('aria-hidden','true');const bar=document.createElement('span');progress.append(bar);video.addEventListener('timeupdate',()=>{bar.style.transform='scaleX('+(video.duration?video.currentTime/video.duration:0)+')'});bottom.append(caption,controls,progress);const error=document.createElement('a');error.className='reel-error';error.href=reel.url;error.target='_blank';error.rel='noopener';error.textContent='Ver este reel en Instagram ';error.append(corteIcon('ne'));error.hidden=true;video.addEventListener('error',()=>{error.hidden=false});card.append(video,top,bottom,error);observer.observe(video);return card}
fetch('assets/reels.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{const reels=(Array.isArray(data)?data:data.reels).slice(0,20);total=reels.length;track.replaceChildren(...reels.map(reelCard));updatePosition()}).catch(()=>{$('#reels-status').textContent='Reels en Instagram';const link=document.createElement('a');link.className='button';link.href='https://www.instagram.com/lacorteitaliana/reels/';link.textContent='Abrir los reels en Instagram ';link.append(corteIcon('ne'));track.append(link)});
document.addEventListener('click',e=>{if(!e.target.closest('.reel-top'))document.querySelectorAll('.reel-menu').forEach(m=>{m.hidden=true;m.previousElementSibling?.setAttribute('aria-expanded','false')})});

